-- lang_resources：<1.12.0 全部迁移的最终状态 dump（schema + 种子数据）
CREATE TABLE lang_resources
(
    `id` INTEGER PRIMARY KEY AUTOINCREMENT,
    lang_type   varchar(32),
    lang_base   varchar(32),
    lang_code   varchar(128) not null,
    lang_value  varchar(512) not null,
    lang_extend varchar(512)
    
);
CREATE INDEX `lang_resources_idx_lang_code` ON `lang_resources` (lang_code);
